const secretKey = process.env.NEXT_PUBLIC_PAYMENT_SECRET_KEY;

export async function createCharge(amount: number) {
  const res = await fetch(`${process.env.API_BASE}/charges`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${secretKey}` },
    body: JSON.stringify({ amount }),
  });
  return res.json();
}

